SELECT * FROM social_location_jobs
WHERE user_id = #{userId}
  AND status = 'COMPLETED'
  AND result_payload IS NOT NULL

  AND id IN

      #{id}


ORDER BY created_at DESC
LIMIT #{limit}

SELECT * FROM social_location_jobs
WHERE status = 'DISPATCHING'
  AND updated_at <= #{cutoff}
ORDER BY updated_at
LIMIT #{limit}
